{
  "master_id": "benson",
  "work_id": "method-vol-3-technique-arpeggios",
  "usage_notes": [
    {
      "chord_quality": "maj7",
      "function_role": "tonic-imaj7-avoid-note-target",
      "narrative": "For Cmaj7 (Imaj7), Benson prescribes descending 'Major 7th Scale Arpeggios' -- Cmaj7 arpeggios with added color tones transcribed from Benson's own solos -- organized zone-by-zone across the fretboard, to sidestep the perfect 4th avoid note. 'We will create melodies for Cmaj7 that can fit over Ionian or Lydian chords.' These are descending arpeggios with added notes, each zone providing a 'guide idea starting from the highest note and ending in the lowest note.' Chapter 7, p. 269.",
      "source_principle_ids": [
        "benson:method-vol-3-technique-arpeggios:chord-arpeggio-construction",
        "benson:method-vol-3-technique-arpeggios:superimposition-vocabulary"
      ],
      "source_work_id": "method-vol-3-technique-arpeggios",
