          "citation": "chapter 7 p.269"
        }
      ],
      "provenance": "extracted"
    },
    {
      "chord_quality": "maj7",
      "function_role": "tonic-imaj7-avoid-note-prohibition",
      "narrative": "The perfect 4th is an avoid note over Cmaj7 (Imaj7) and must not be used as a default melodic choice. 'The avoid note (perfect 4th) can create some melodic problems, especially over the root chord and the relative minor chord (Cmaj7 and Am7 in the key of C).' Exceptions exist: 'there are always exceptions and at times the avoid note works fine depending on the situation.' Chapter 6, p. 244; Chapter 7, p. 269.",
      "source_principle_ids": [
        "benson:method-vol-3-technique-arpeggios:superimposition-vocabulary"
      ],
      "source_work_id": "method-vol-3-technique-arpeggios",
      "references": [
        {
          "source": "method-vol-3-technique-arpeggios",
          "citation": "chapter 6 p.244"
        },
        {
          "source": "method-vol-3-technique-arpeggios",
          "citation": "chapter 7 p.269"
        }
      ],
      "provenance": "extracted",
      "polarity": "proscriptive",
      "cross_ref": [
        "avoid-note-exception-imaj7"
      ]
    },
    {
      "chord_quality": "maj7",
      "function_role": "tonic-imaj7-avoid-note-exception",
      "narrative": "Although the perfect 4th is proscribed over Cmaj7 by default, Benson explicitly acknowledges contextual exceptions: 'there are always exceptions and at times the avoid note works fine depending on the situation.' The player must judge the musical context. Chapter 6, p. 244.",
      "source_principle_ids": [
        "benson:method-vol-3-technique-arpeggios:superimposition-vocabulary"
      ],
      "source_work_id": "method-vol-3-technique-arpeggios",
      "references": [
        {
          "source": "method-vol-3-technique-arpeggios",
          "citation": "chapter 6 p.244"
        }
