          "citation": "chapter 5 p.195"
        }
      ],
      "provenance": "extracted"
    },
    {
      "chord_quality": "maj7",
      "function_role": "tonic-imaj7-descending-arpeggio-spans-two-zones",
      "narrative": "For Cmaj7 scale arpeggios, Benson prescribes awareness that descending arpeggios span two fretboard zones while ascending arpeggios define a single zone: 'Notice that the ascending arpeggios will define the fretboard zones, because the descending arpeggios will almost always use two zones, because we play descending arpeggios vertically.' Ascending forms orient position; descending forms are the primary melodic vehicle over Imaj7. Chapter 7, p. 275.",
      "source_principle_ids": [
        "benson:method-vol-3-technique-arpeggios:chord-arpeggio-construction"
      ],
      "source_work_id": "method-vol-3-technique-arpeggios",
      "references": [
        {
          "source": "method-vol-3-technique-arpeggios",
          "citation": "chapter 7 p.275"
        }
      ],
      "provenance": "extracted"
    },
    {
      "chord_quality": "min7",
      "function_role": "relative-minor-vim7-descending-arpeggio-spans-two-zones",
      "narrative": "For Am7 scale arpeggios, Benson prescribes the same zone-spanning rule as for Cmaj7: ascending Am7 arpeggios define the fretboard zone, while descending Am7 arpeggios with added notes span two zones. 'The ascending arpeggios will define the fretboard zones, because the descending arpeggios will almost always use two zones.' The descending form is the primary melodic vehicle over VIm7. Chapter 7, p. 275.",
      "source_principle_ids": [
        "benson:method-vol-3-technique-arpeggios:chord-arpeggio-construction"
      ],
      "source_work_id": "method-vol-3-technique-arpeggios",
      "references": [
        {
          "source": "method-vol-3-technique-arpeggios",
          "citation": "chapter 7 p.275"
        }
      ],
      "provenance": "extracted"
    },
    {
      "chord_quality": "maj7",
      "function_role": "tonic-imaj7-pattern-exercise-scaffold-only",
